CREATE TABLE THIRD_PARTY_FORM_SUBMISSION (
    SUBMISSION_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    LINK_ID NUMBER NOT NULL,
    DOCUMENT_RECEIVE_NO VARCHAR2(100),
    FILLED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    FULL_NAME_TH VARCHAR2(255) NOT NULL,
    FULL_NAME_EN VARCHAR2(255),
    ORGANIZATION VARCHAR2(255) NOT NULL,
    PHONE VARCHAR2(50) NOT NULL,
    EMAIL VARCHAR2(320) NOT NULL,
    REASON_OBJECTIVE CLOB NOT NULL,
    PROJECT_NAME VARCHAR2(500),
    ACCESS_START_DATE DATE NOT NULL,
    ACCESS_END_DATE DATE NOT NULL,
    STATUS VARCHAR2(30) DEFAULT 'PENDING_REVIEW' NOT NULL,
    CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    REVIEWED_BY NUMBER,
    REVIEWED_AT TIMESTAMP,
    IMPORTED_FORMID NUMBER,
    INTERNAL_NOTE VARCHAR2(1000),
    CONSENT_ACCEPTED NUMBER(1) DEFAULT 0 NOT NULL,
    CONSENT_VERSION VARCHAR2(50),
    CONSENT_ACCEPTED_AT TIMESTAMP,
    CONSENT_IP_ADDRESS VARCHAR2(45),
    CONSENT_USER_AGENT VARCHAR2(500),
    CONSTRAINT FK_THIRD_PARTY_SUB_LINK FOREIGN KEY (LINK_ID)
        REFERENCES THIRD_PARTY_FORM_LINK (LINK_ID),
    CONSTRAINT UQ_THIRD_PARTY_SUB_LINK UNIQUE (LINK_ID),
    CONSTRAINT CHK_THIRD_PARTY_SUB_CONSENT_ACCEPTED CHECK (CONSENT_ACCEPTED IN (0, 1)),
    CONSTRAINT CHK_THIRD_PARTY_SUB_STATUS CHECK (
        STATUS IN ('PENDING_REVIEW', 'IMPORTED', 'REJECTED')
    ),
    CONSTRAINT CHK_THIRD_PARTY_SUB_DATE_RANGE CHECK (
        ACCESS_END_DATE >= ACCESS_START_DATE
    )
);

CREATE UNIQUE INDEX UQ_THIRD_PARTY_SUB_DOC_NO
    ON THIRD_PARTY_FORM_SUBMISSION (DOCUMENT_RECEIVE_NO);

CREATE INDEX IX_THIRD_PARTY_SUB_STATUS
    ON THIRD_PARTY_FORM_SUBMISSION (STATUS, CREATED_AT);

CREATE INDEX IX_THIRD_PARTY_SUB_EMAIL
    ON THIRD_PARTY_FORM_SUBMISSION (EMAIL);
